mapper.select:
SELECT id, user_id, fingerprint, device_name, endpoint, metadata_json, last_seen_at, created_at, updated_at
FROM runtime_device
WHERE fingerprint = #{_parameter}

mapper.insert:
INSERT INTO runtime_device (
    id, user_id, fingerprint, device_name, endpoint, metadata_json, last_seen_at, created_at, updated_at
) VALUES (
    #{id}, #{userId}, #{fingerprint}, #{deviceName}, #{endpoint}, #{metadataJson}, #{lastSeenAt}, #{createdAt}, #{updatedAt}
)

INSERT INTO runtime_event (
    id, user_id, device_id, event_type, session_id, payload_json, created_at
) VALUES (
    #{id}, #{userId}, #{deviceId}, #{eventType}, #{sessionId}, #{payloadJson}, #{createdAt}
)

mapper.select:
SELECT id, user_id, device_id, event_type, session_id, payload_json, created_at
FROM runtime_event

    user_id = #{userId}

        AND session_id = #{sessionId}


        AND event_type = #{eventType}


        AND payload_json LIKE CONCAT('%', #{traceId}, '%')


ORDER BY created_at DESC
LIMIT #{normalizedLimit}
